"""Left R48 tunnel generated by mirroring the unmarked right-hand CAD."""
from pathlib import Path
from parts.gentle_curve_tunnel.design import (
    LEFT_PART_ID as PART_ID, build_part, export as shared_export,
)

SOURCE_VERSION = "E01-V3"


def export(out=Path("build/gentle-curve-tunnel-left")):
    return shared_export(out, direction="left")


if __name__ == "__main__":
    import argparse
    parser = argparse.ArgumentParser()
    parser.add_argument("--out", type=Path, default=Path("build/gentle-curve-tunnel-left"))
    export(parser.parse_args().out)
